"""Types shared by more than one generated Bybit endpoint."""

from typing_extensions import Literal, TypedDict

KlineInterval = Literal[
  '1', '3', '5', '15', '30', '60', '120', '240', '360', '720', 'D', 'W', 'M'
]

MetricInterval = Literal['5min', '15min', '30min', '1h', '4h', '1d']

OrderbookLevel = tuple[str, str]


class RiskParameters(TypedDict):
  """Price bands applied to limit orders."""

  priceLimitRatioX: str
  """Ratio `X` of the limit order price band."""
  priceLimitRatioY: str
  """Ratio `Y` of the limit order price band."""
